import json
invalid=[]; total=0
with open('scratch/events.jsonl','rb') as f:
    for i,raw in enumerate(f,1):
        line=raw.decode('utf-8')
        if not line.strip():
            invalid.append(i); continue
        try:
            obj=json.loads(line)
        except Exception:
            invalid.append(i); continue
        if not isinstance(obj,dict):
            invalid.append(i); continue
        v=obj.get('value')
        if isinstance(v,int) and not isinstance(v,bool):
            total+=v
with open('scratch/result.json','w',encoding='utf-8') as f:
    json.dump({"sum":total,"invalid_lines":invalid},f,ensure_ascii=False)
print(total,invalid)
EOF
md5sum -c /tmp/before.md5; cat scratch/result.json","label":"Compute sum and write result"}

